def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = 0
    my_d = 0
    cc = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1
        if a == 'C' and b == 'C':
            cc += 1

    # Last action info
    last_my, last_opp = history[-1]
    remaining = 100 - n

    # Very short match start: cooperate, but if opponent opened with D, hit back once then reset.
    if n <= 3:
        if opp_d == 0:
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Endgame: extract maximum value. Against mostly-cooperative opp, defect;
    # against mostly-defective opp, mostly defect with rare probes.
    if remaining <= 8:
        if opp_d <= 2:
            return 'D'
        if opp_d * 4 >= n * 3:
            return 'D' if (n + cc) % 4 != 0 else 'C'
        return 'D'

    # Detect opponent's cooperation tendency.
    opp_rate = (n - opp_d) / n

    # Almost always cooperating opponent: exploit but keep just enough C to
    # sustain their cooperation until near the end.
    if opp_d == 0:
        if n < 90:
            # Rare probe to check if they retaliate. If history shows they never
            # punish (which it will if opp_d stays 0), ramp up exploitation.
            if n >= 20 and rng.random() < 0.15:
                return 'D'
            if n >= 50 and rng.random() < 0.35:
                return 'D'
            return 'C'
        return 'D'

    if opp_rate >= 0.9 and n >= 12:
        # If opp never retaliated to our prior D's, keep defecting.
        # Otherwise cooperate mostly.
        if my_d > 0 and opp_d <= 1:
            return 'D'
        if n < 80 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Nearly always defecting opponent: defect, with rare C to test for
    # responsiveness (some strategies trigger kindness when we cooperate).
    if opp_rate <= 0.15:
        # If opponent has ever cooperated immediately after our C, keep
        # probing; otherwise pure D.
        if n >= 6:
            probed = False
            for i in range(n - 1):
                if history[i][0] == 'C' and history[i + 1][1] == 'C':
                    probed = True
                    break
            if probed and rng.random() < 0.25:
                return 'C'
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    # General reactive zone. Use forgiveness-based reciprocity:
    # cooperate unless opponent has recently defected enough.
    recent = history[-10:]
    rlen = len(recent)
    recent_opp_d = sum(1 for a, b in recent if b == 'D')
    recent_my_d = sum(1 for a, b in recent if a == 'D')

    # If we're stuck in mutual defection, occasionally extend an olive branch.
    if last_my == 'D' and last_opp == 'D':
        if recent_my_d >= 4 and recent_opp_d >= 4:
            if rng.random() < 0.35:
                return 'C'

    # Strong retaliation for recent defections.
    if recent_opp_d * 2 >= rlen and rlen >= 4:
        if last_opp == 'D':
            return 'D'
        # Opponent cooperated after a bad streak: reciprocate to rebuild.
        return 'C'

    # Opponent's last action drives default reciprocity.
    if last_opp == 'D':
        # Forgive a single defection if opp is generally cooperative.
        if opp_rate >= 0.7 and recent_opp_d <= 1:
            return 'C'
        return 'D'

    # Opponent cooperated: cooperate, but occasionally exploit very
    # cooperative opponents in mid-game.
    if opp_rate >= 0.85 and 15 <= n < 85:
        if rng.random() < 0.08:
            return 'D'
    if opp_rate >= 0.65 and rng.random() < 0.04:
        return 'D'

    # If we've been defecting too often relative to opp, return to C to
    # avoid unnecessary mutual-defection losses.
    if recent_my_d > recent_opp_d + 2:
        return 'C'

    return 'C'
